import { JsonRpcProvider, Interface } from "ethers";
import fs from "fs";
import "dotenv/config";
import { encodeAbiParameters, encodePacked, keccak256, createPublicClient, http } from "viem";
import { getBytecode, createConfig, readContract } from "@wagmi/core";
import { participants } from "./participants.js";
import { optimism } from "viem/chains";

const TradeExecutorBytecode =
  "";
const config = createConfig({
  chains: [optimism],
  transports: {
    [optimism.id]: http(process.env.RPC_URL),
  },
});

function formatBytecode(bytecode) {
  // Remove any whitespace
  const cleaned = bytecode.trim();

  // Add 0x prefix if not present
  if (!cleaned.startsWith("0x")) {
    return `0x${cleaned}`;
  }

  return cleaned;
}
function predictFactoryAddress({ factoryAddress, salt, deploymentData }) {
  const initCodeHash = keccak256(deploymentData);

  const create2Input = encodePacked(
    ["bytes1", "address", "bytes32", "bytes32"],
    ["0xff", factoryAddress, salt, initCodeHash],
  );

  const hash = keccak256(create2Input);
  return `0x${hash.slice(-40)}`;
}
async function checkTradeExecutorCreated(account) {
  const constructorData = encodeAbiParameters([{ type: "address" }], [account]);
  const deploymentData = `${formatBytecode(TradeExecutorBytecode)}${constructorData.slice(2)}`;
  const salt = keccak256(encodePacked(["string", "address"], ["TradeExecutorV1", account]));

  // Predict contract address
  const predictedAddress = predictFactoryAddress({
    factoryAddress: "0x6F6537809831605f6920eF623B9dd8a6036bbc60",
    salt,
    deploymentData,
  });

  // Check if already deployed
  const code = await getBytecode(config, {
    address: predictedAddress,
  });

  if (code && code !== "0x") {
    return { isCreated: true, predictedAddress, account };
  }
  return { isCreated: false };
}
async function checkBalance(account, predictedAddress) {
  const balance = await readContract(config, {
    address: "0x7f5866a4204ddce2c95355d4b265b2b54b5d7365",
    abi: [
      {
        name: "balanceOf",
        type: "function",
        stateMutability: "view",
        inputs: [{ type: "address" }],
        outputs: [{ type: "uint256" }],
      },
    ],
    functionName: "balanceOf",
    args: [predictedAddress],
  });
  return { account, balance, predictedAddress };
}
async function main() {
  const createdWallets = (
    await Promise.all(participants.map((acc) => checkTradeExecutorCreated(acc)))
  ).filter((x) => x.isCreated);
  const l2Users = (
    await Promise.all(createdWallets.map((x) => checkBalance(x.account, x.predictedAddress)))
  ).filter((x) => x.balance);
  fs.writeFileSync(
    "l2-participants.json",
    JSON.stringify(
      l2Users.map((x) => x.account),
      null,
      4,
    ),
  );
  console.log(l2Users.length);
}
main();
